CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY CHECK(id GLOB 'usr_*'), display_name TEXT NOT NULL, created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS agents (id TEXT PRIMARY KEY CHECK(id GLOB 'agt_*'), owner_user_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, created_at TEXT NOT NULL); CREATE UNIQUE INDEX IF NOT EXISTS agents_owner_name ON agents(owner_user_id,name);